(function(){'use strict';const status=document.getElementById('operator-status'),body=document.getElementById('operator-rows'),button=document.getElementById('refresh');
async function load(){button.disabled=true;status.textContent='Loading private applications…';try{const r=await fetch('/api/partners/admin/applications',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(12000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Operator verification failed');body.replaceChildren();const rows=Array.isArray(d.applications)?d.applications:[];if(!rows.length){const tr=body.insertRow();const cell=tr.insertCell();cell.colSpan=7;cell.textContent='No submitted applications yet.';}for(const a of rows){const tr=body.insertRow();const date=a.created_at?new Date(a.created_at).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'}):'—';const fields=[date,(a.contact_name||'')+' · '+(a.email||''),(a.organisation||'Independent')+' · '+(a.region||''),a.role||'',a.channel||'',a.experience||'',a.status||'pending'];for(const value of fields){tr.insertCell().textContent=value;}}status.textContent=rows.length+' application'+(rows.length===1?'':'s')+' listed · manually reviewed, not approved by this page.';}
catch(e){status.textContent='Applications could not be displayed: '+e.message;body.replaceChildren();const tr=body.insertRow();const cell=tr.insertCell();cell.colSpan=7;cell.textContent='No data displayed.'}finally{button.disabled=false;}}
button.addEventListener('click',load);load();})();